def longestSubseqAtMost(s, k):
    length = 0
    value = 0
    weight = 1
    for c in reversed(s):
        if c == '0':
            length += 1
        elif value + weight <= k:
            value += weight
            length += 1
        else:
            continue
        if weight <= k:
            weight *= 2
    return length
